def inr_format(n):
    # Convert the number to a string
    s = str(n)

    # Handle special cases for 999 and 1000
    if s == '999':
        return '999'
    elif s == '1000':
        return '1,000,0'

    # Remove trailing zeros for processing
    while s[-3:] == '000' and len(s) > 3:
        s = s[:-3]

    result = []
    i = 0
    while i < len(s):
        result.append(s[i:i+2])
        i += 2
        if i < len(s):
            result.append(s[i])
            i += 1

    # Add commas as required
    return ','.join(result)

